/// <summary>
/// Service class for MET Customer MDF consolidation batch processing
/// </summary>
class METCustomerMDFConsolidationBatchService extends METSysOperationService
{
    private guid                   topPickingProcessId;
}

Method.Source:
/// <summary>
/// Returns task service class name.
/// </summary>
/// <returns>Task service class name</returns>
protected str getTaskServiceClass()
{
    return classStr(METCustomerMDFConsolidationBatchTaskService);
}

/// <summary>
/// Returns task service class method.
/// </summary>
/// <returns>Task service class method</returns>
protected str getTaskServiceClassMethod()
{
    return methodStr(METCustomerMDFConsolidationBatchTaskService, process);
}

/// <summary>
/// Returns caption of the task service class.
/// </summary>
/// <returns>Task service class caption</returns>
protected str getTaskServiceCaption()
{
    return "MDF Free text invoice generation";
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METSysOperationTaskDataContract</c>
/// </param>
public void process(METCustomerMDFConsolidationBatchContract _contract)
{
    this.processInternal(_contract);
}

/// <summary>
/// Initialise global variables.
/// </summary>
public void initialise()
{
    super();

    this.stageDataIntoQueue();
}

/// <summary>
/// Initializes the task data contract.
/// </summary>
/// <param name = "_taskDataContract">task data contract</param>
protected void initTaskDataContract(METSysOperationTaskDataContract _taskDataContract)
{
    super(_taskDataContract);
    METCustomerMDFConsolidationBatchContract contract = _taskDataContract as METCustomerMDFConsolidationBatchContract;
    contract.parmTopPickingProcessId(topPickingProcessId);
}

/// <summary>
/// Data contract object
/// </summary>
/// <returns></returns>
protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METCustomerMDFConsolidationBatchContract();
}

/// <summary>
/// Stages data int table <c>METCustomerMDFConsolidationBatchJobQueue</c>.
/// </summary>
void stageDataIntoQueue()
{
    #OCCRetryCount

    try
    {
        ttsbegin;

        METCustomerMDFConsolidationBatchJobQueue::cleanUpJobQueue();

        RecordInsertList jobQueueRecordList;
        METCustomerMDFConsolidationBatchJobQueue jobQueue;
        QueryRun queryRun;
        METCustomerMDFConsolidationBatchContract contract;


        jobQueueRecordList = new RecordInsertList(tableNum(METCustomerMDFConsolidationBatchJobQueue));
        topPickingProcessId = newGuid();
        contract = dataContract as METCustomerMDFConsolidationBatchContract;

        queryRun = new QueryRun(contract.getQuery());

        while (queryRun.next())
        {
            MetCustomerMdfTable customerMdfTable = queryRun.get(tableNum(MetCustomerMdfTable));

            jobQueue.clear();
            jobQueue.ProcessId = topPickingProcessId;
            jobQueue.CustAccount = customerMdfTable.CustAccount;

            jobQueueRecordList.add(jobQueue);
        }

        jobQueueRecordList.insertDatabase();

        ttscommit;

    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::Deadlock;
        }
        else
        {
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch (Exception::Error)
    {
        // catch the errors so processing can continue
        curext(); // avoids a warning about an empty block
    }
}
